@using Umbraco.Cms.Core.Models.PublishedContent
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@{
    Layout = null;
    var posts = Model.Descendants().Where(x => x.ContentType.Alias == "blogPost" && x.IsVisible()).OrderByDescending(x => x.Value<DateTime>("publishDate"));
}
<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8" /><title>@Model.Value("title")</title><meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="/css/site.css" />
    <script src="/scripts/site.js" defer></script>
</head>
<body>
    @await Html.PartialAsync("header")
    <main>
    <h1>@Model.Value("title")</h1>
    <p>@Model.Value("intro")</p>
    <ul class="posts">
    @foreach (var post in posts)
    {
        var image = post.Value<IPublishedContent>("featuredImage");
        <li>
            @if (image != null) { <img src="@image.GetCropUrl(width: 300)" alt="" /> }
            <h2><a href="@post.Url()">@post.Value("title")</a></h2>
            <p><small>@(post.Value<DateTime>("publishDate").ToString("d MMM yyyy")) · @post.Value("author")</small></p>
            <p>@post.Value("excerpt")</p>
        </li>
    }
    </ul>
    </main>
    @await Html.PartialAsync("footer")
</body>
</html>

@using Umbraco.Cms.Core.Models.PublishedContent
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@{
    Layout = null;
    var image = Model.Value<IPublishedContent>("featuredImage");
    var related = Model.Value<IPublishedContent>("relatedPost");
    var metaTitle = Model.Value<string>("metaTitle");
}
<!DOCTYPE html>
<html lang="@(System.Globalization.CultureInfo.CurrentCulture.Name)">
<head>
    <meta charset="utf-8" />
    <title>@(string.IsNullOrWhiteSpace(metaTitle) ? Model.Value("title") : metaTitle)</title>
    <meta name="description" content="@Model.Value("metaDescription")" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="/css/site.css" />
    <script src="/scripts/site.js" defer></script>
</head>
<body>
    @await Html.PartialAsync("header")
    <main>
    <article>
        @if (Model.Value<bool>("isFeatured")) { <strong>★ @Umbraco.GetDictionaryValue("Blog.Featured")</strong> }
        <h1>@Model.Value("title")</h1>
        <p><small>@(Model.Value<DateTime>("publishDate").ToString("d MMMM yyyy")) · @Model.Value("author") · @Model.Value("readingTime") @Umbraco.GetDictionaryValue("Blog.MinRead")</small></p>
        <p>@Umbraco.GetDictionaryValue("Blog.Categories"): @string.Join(", ", Model.Value<IEnumerable<string>>("categories") ?? Enumerable.Empty<string>())</p>
        @if (image != null) { <img src="@image.GetCropUrl(width: 1200)" alt="" /> }
        <p><em>@Model.Value("excerpt")</em></p>
        <div>@Model.Value("bodyText")</div>
        <p>@Umbraco.GetDictionaryValue("Blog.Tags"): @string.Join(", ", Model.Value<IEnumerable<string>>("tags") ?? Enumerable.Empty<string>())</p>
        @if (related != null) { <p>@Umbraco.GetDictionaryValue("Blog.Related"): <a href="@related.Url()">@related.Name</a></p> }
    </article>
    </main>
    @await Html.PartialAsync("footer")
</body>
</html>

@using Umbraco.Cms.Core.Security
@using Umbraco.Cms.Web.Website.Controllers
@using Umbraco.Cms.Web.Website.Models
@using UmbracoSite.Controllers
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@inject IMemberManager MemberManager
@{
    Layout = null;
    string T(string key) => Umbraco.GetDictionaryValue(key) ?? key;
    var member = await MemberManager.GetCurrentMemberAsync();
    var contactSent = TempData["contactSuccess"] is true;
    var signedUp = TempData["signupSuccess"] is true;
}
<!DOCTYPE html>
<html lang="@(System.Globalization.CultureInfo.CurrentCulture.Name)">
<head>
    <meta charset="utf-8" />
    <title>@Model.Value("title")</title>
<meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="/css/site.css" />
    <script src="/scripts/site.js" defer></script>
</head>
<body>
    @await Html.PartialAsync("header")
    <main>
    <h1>@Model.Value("title")</h1>
    @Model.Value("intro")

    <section id="contact">
        @if (contactSent)
        {
            <p class="success" id="contact-success">@Model.Value("successMessage")</p>
        }
        else
        {
            using (Html.BeginUmbracoForm<ContactSurfaceController>(nameof(ContactSurfaceController.Submit), null, new { id = "contact-form" }))
            {
                @Html.ValidationSummary()
                <p><label>@T("Form.Name")<br /><input name="Name" required maxlength="100" /></label></p>
                <p><label>@T("Form.Email")<br /><input name="Email" type="email" required /></label></p>
                <p><label>@T("Form.Subject")<br /><input name="Subject" maxlength="150" /></label></p>
                <p><label>@T("Form.Message")<br /><textarea name="Message" rows="6" required></textarea></label></p>
                <button type="submit">@T("Form.Send")</button>
            }
        }
    </section>

    <section id="signup">
        <h2>@Model.Value("signupTitle")</h2>
        @if (signedUp)
        {
            <p class="success" id="signup-success">@Model.Value("signupSuccessMessage")</p>
        }
        @if (member is not null)
        {
            <p id="signed-in">@T("Form.SignedInAs") <strong>@member.Name</strong> (@member.Email)</p>
            using (Html.BeginUmbracoForm<UmbLoginStatusController>("HandleLogout", new { RedirectUrl = Model.Url() }))
            {
                <button type="submit">@T("Form.SignOut")</button>
            }
        }
        else
        {
            @Model.Value("signupIntro")
            using (Html.BeginUmbracoForm<ContactSurfaceController>(nameof(ContactSurfaceController.SignUp), null, new { id = "signup-form" }))
            {
                <p><label>@T("Form.Name")<br /><input name="Name" required maxlength="100" /></label></p>
                <p><label>@T("Form.Email")<br /><input name="Email" type="email" required /></label></p>
                <p><label>@T("Form.Password")<br /><input name="Password" type="password" required minlength="10" /></label></p>
                <p><label>@T("Form.Company")<br /><input name="Company" maxlength="100" /></label></p>
                <p><label><input name="MarketingOptIn" type="checkbox" value="true" /> @T("Form.MarketingOptIn")</label></p>
                <button type="submit">@T("Form.SignUp")</button>
            }
        }
    </section>
    </main>
    @await Html.PartialAsync("footer")
</body>
</html>

@using Umbraco.Cms.Core.Models.Blocks
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage
@{
	Layout = null;
	var blocks = Model.Value<BlockListModel>("blocks");
}
<!DOCTYPE html>
<html lang="@(System.Globalization.CultureInfo.CurrentCulture.Name)">
<head>
    <meta charset="utf-8" />
    <title>@Model.Value("title")</title>
<meta name="viewport" content="width=device-width, initial-scale=1" />
    <link rel="stylesheet" href="/css/site.css" />
    <script src="/scripts/site.js" defer></script>
</head>
<body>
    @await Html.PartialAsync("header")
    <main>
    <h1>@Model.Value("title")</h1>
    <div>@Model.Value("bodyText")</div>
    @if (blocks?.Any() == true)
    {
        <div class="blocks">@await Html.GetBlockListHtmlAsync(blocks)</div>
    }
    </main>
    @await Html.PartialAsync("footer")
</body>
</html>
